mapper.update:
UPDATE product_sku
SET deleted = 1, version = version + 1
WHERE spu_id = #{spuId,jdbcType=BIGINT}

mapper.select:
SELECT 
FROM product_sku

    AND deleted = 0

        AND spu_id = #{query.spuId,jdbcType=BIGINT}


        AND sku_code = #{query.skuCode,jdbcType=VARCHAR}


        AND enable_status = #{query.enableStatus,jdbcType=TINYINT}


        AND base_price >= #{query.basePriceStart,jdbcType=DECIMAL}


        AND base_price <= #{query.basePriceEnd,jdbcType=DECIMAL}


        AND attr_values LIKE CONCAT('%', #{query.specKeyword,jdbcType=VARCHAR}, '%')


ORDER BY id DESC
